[{"order":1,"type":"heading","text":"Content Providers & Inter-Process Communication (IPC) in Android (Java)"},{"order":2,"type":"paragraph","text":"Content Providers are a foundational component of Android. They manage access to a central repository of data and provide a standard interface for Inter-Process Communication (IPC), allowing secure data sharing across different applications."},{"order":3,"type":"subheading","text":"How IPC Works in Content Providers"},{"order":4,"type":"paragraph","text":"Under the hood, Android Content Providers rely on the Binder mechanism for IPC. When an application queries a Content Provider belonging to another process, the framework marshals the parameters, sends them across process boundaries via the Binder driver, executes the query in the provider process, and returns the results as a Cursor object."},{"order":5,"type":"subheading","text":"Step 1: Implementing the Content Provider"},{"order":6,"type":"paragraph","text":"To create a custom Content Provider, extend the ContentProvider class and override its core CRUD methods: query, insert, update, delete, and getType."},{"order":7,"type":"code","text":"public class UserContentProvider extends ContentProvider {
    private static final String AUTHORITY = "com.example.provider.userprovider";
    public static final Uri CONTENT_URI = Uri.parse("content://" + AUTHORITY + "/users");

    private static final int USERS = 1;
    private static final UriMatcher uriMatcher = new UriMatcher(UriMatcher.NO_MATCH);

    static {
        uriMatcher.addURI(AUTHORITY, "users", USERS);
    }

    private UserDatabaseHelper dbHelper;

    @Override
    public boolean onCreate() {
        dbHelper = new UserDatabaseHelper(getContext());
        return true;
    }

    @Override
    public Cursor query(Uri uri, String[] projection, String selection, String[] selectionArgs, String sortOrder) {
        SQLiteDatabase db = dbHelper.getReadableDatabase();
        Cursor cursor;

        switch (uriMatcher.match(uri)) {
            case USERS:
                cursor = db.query("users", projection, selection, selectionArgs, null, null, sortOrder);
                break;
            default:
                throw new IllegalArgumentException("Unknown URI: " + uri);
        }

        cursor.setNotificationUri(getContext().getContentResolver(), uri);
        return cursor;
    }

    @Override
    public String getType(Uri uri) {
        switch (uriMatcher.match(uri)) {
            case USERS:
                return "vnd.android.cursor.dir/vnd.com.example.provider.users";
            default:
                throw new IllegalArgumentException("Unsupported URI: " + uri);
        }
    }

    @Override
    public Uri insert(Uri uri, ContentValues values) {
        SQLiteDatabase db = dbHelper.getWritableDatabase();
        long id = db.insert("users", null, values);
        if (id > 0) {
            Uri returnUri = ContentUris.withAppendedId(CONTENT_URI, id);
            getContext().getContentResolver().notifyChange(returnUri, null);
            return returnUri;
        }
        throw new SQLException("Failed to insert row into " + uri);
    }

    @Override
    public int delete(Uri uri, String selection, String[] selectionArgs) {
        SQLiteDatabase db = dbHelper.getWritableDatabase();
        int count = db.delete("users", selection, selectionArgs);
        getContext().getContentResolver().notifyChange(uri, null);
        return count;
    }

    @Override
    public int update(Uri uri, ContentValues values, String selection, String[] selectionArgs) {
        SQLiteDatabase db = dbHelper.getWritableDatabase();
        int count = db.update("users", values, selection, selectionArgs);
        getContext().getContentResolver().notifyChange(uri, null);
        return count;
    }
}"},{"order":8,"type":"subheading","text":"Step 2: Declaring the Provider in Manifest"},{"order":9,"type":"paragraph","text":"To make the Content Provider accessible to other applications, declare it in the AndroidManifest.xml file using the android:exported attribute set to true."},{"order":10,"type":"code","text":"<provider
    android:name=".UserContentProvider"
    android:authorities="com.example.provider.userprovider"
    android:exported="true"
    android:readPermission="com.example.provider.READ_DATA"
    android:writePermission="com.example.provider.WRITE_DATA" />"},{"order":11,"type":"subheading","text":"Step 3: Consuming the Content Provider from Another App"},{"order":12,"type":"paragraph","text":"A client application interacts with the Content Provider using the ContentResolver instance obtained from the Context."},{"order":13,"type":"code","text":"Uri uri = Uri.parse("content://com.example.provider.userprovider/users");
ContentResolver resolver = getContentResolver();

// Querying data across processes
Cursor cursor = resolver.query(uri, null, null, null, null);
if (cursor != null) {
    while (cursor.moveToNext()) {
        String username = cursor.getString(cursor.getColumnIndexOrThrow("username"));
        Log.d("IPC_CLIENT", "Fetched User: " + username);
    }
    cursor.close();
}"},{"order":14,"type":"subheading","text":"Best Practices for IPC Security and Performance"},{"order":15,"type":"bullet_point","text":"Permissions: Always secure your exported providers using readPermission and writePermission attributes to control which external apps can access your data."},{"order":16,"type":"bullet_point","text":"Input Validation: Validate all incoming selections and projection arguments carefully to prevent SQL injection vulnerabilities."},{"order":17,"type":"bullet_point","text":"Background Threads: ContentResolver queries can be slow because of IPC overhead. Execute them using CursorLoader or asynchronous background threads to avoid blocking the UI thread."}]
